examples.template:
MonarchButton(text = {{trigger}}, onClick = { open = true }, variant = MonarchButtonVariant.Secondary)
if (open) {
    Dialog(
        onDismissRequest = { if (!merging) open = false },
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        // A centred dialog card with a margin round it, as on the web, not a full screen.
        Surface(
            modifier = Modifier
                .padding(horizontal = MonarchTheme.spacing.space4, vertical = MonarchTheme.spacing.space6)
                .fillMaxWidth()
                .heightIn(max = 1000.dp),
            shape = MonarchTheme.shapes.xl,
            color = MonarchTheme.colors.bgSurface,
        ) {
            MonarchMergeDialog(
                records = listOf(
                    MonarchMergeRecord({{records.0.id}}, {{records.0.title}}, description = {{records.0.description}}, values = mapOf("name" to {{records.0.values.name}}, "email" to {{records.0.values.email}}, "phone" to {{records.0.values.phone}}, "website" to {{records.0.values.website}}, "city" to {{records.0.values.city}})),
                    MonarchMergeRecord({{records.1.id}}, {{records.1.title}}, description = {{records.1.description}}, values = mapOf("name" to {{records.1.values.name}}, "email" to {{records.1.values.email}}, "phone" to {{records.1.values.phone}}, "website" to {{records.1.values.website}}, "city" to {{records.1.values.city}})),
                ),
                fields = listOf(
                    MonarchMergeField({{fields.0.id}}, {{fields.0.label}}),
                    MonarchMergeField({{fields.1.id}}, {{fields.1.label}}),
                    MonarchMergeField({{fields.2.id}}, {{fields.2.label}}),
                    MonarchMergeField({{fields.3.id}}, {{fields.3.label}}),
                    MonarchMergeField({{fields.4.id}}, {{fields.4.label}}),
                ),
                onMerge = { selection ->
                    kept = selection.primaryId
                    merging = true
                },
                consequences = listOf(
                    MonarchConsequence(MonarchConsequenceKind.Changed, {{consequences.0}}),
                    MonarchConsequence(MonarchConsequenceKind.Changed, {{consequences.1}}),
                ),
                merging = merging,
                onCancel = { open = false },
            )
        }
    }
}

