MonarchButton(text = "Merge duplicates", onClick = { open = true }, variant = MonarchButtonVariant.Secondary)
if (open) {
    Dialog(
        onDismissRequest = { if (!merging) open = false },
        properties = DialogProperties(usePlatformDefaultWidth = false),
    ) {
        // A centred dialog card with a margin round it, as on the web, not a full screen.
        Surface(
            modifier = Modifier
                .padding(horizontal = MonarchTheme.spacing.space4, vertical = MonarchTheme.spacing.space6)
                .fillMaxWidth()
                .heightIn(max = 1000.dp),
            shape = MonarchTheme.shapes.xl,
            color = MonarchTheme.colors.bgSurface,
        ) {
            MonarchMergeDialog(
                records = listOf(
                    MonarchMergeRecord("a", "Example Ltd", description = "Created 12 Feb 2025 · 3 projects", values = mapOf("name" to "Example Ltd", "email" to "hello@example.com", "phone" to "", "website" to "example.com", "city" to "Leeds")),
                    MonarchMergeRecord("b", "Example Limited", description = "Created 4 Jun 2025 · 1 invoice", values = mapOf("name" to "Example Limited", "email" to "hello@example.com", "phone" to "+44 20 0000 0000", "website" to "example.com", "city" to "York")),
                ),
                fields = listOf(
                    MonarchMergeField("name", "Name"),
                    MonarchMergeField("email", "Email"),
                    MonarchMergeField("phone", "Phone"),
                    MonarchMergeField("website", "Website"),
                    MonarchMergeField("city", "City"),
                ),
                onMerge = { selection ->
                    kept = selection.primaryId
                    merging = true
                },
                consequences = listOf(
                    MonarchConsequence(MonarchConsequenceKind.Changed, "1 invoice moves to the kept record."),
                    MonarchConsequence(MonarchConsequenceKind.Changed, "The other record is archived, not deleted."),
                ),
                merging = merging,
                onCancel = { open = false },
            )
        }
    }
}
